#include <WiFi.h>

void setup() {
  Serial.begin(115200);
  WiFi.mode(WIFI_STA);
  WiFi.disconnect();
  delay(100);
}

void loop() {
  Serial.println("Scanning Wi-Fi networks...");
  int n = WiFi.scanNetworks();
  Serial.print(n);
  Serial.println(" networks found.");
  delay(5000);
}
